styles.h1:
font-family: "Ma Shan Zheng", "PingFang SC", cursive;
font-size: 32px;
position: relative;
color: #333;
margin-bottom: 20px;
font-weight: 500;
text-align: center;
padding: 10px 0;

styles.h2:
font-size: 18px;
color: #555;
margin-bottom: 24px;
font-weight: 400;
text-align: center;
position: relative;
padding-bottom: 15px;
font-family: "Xingkai SC", "STKaiti", serif;

styles.h3:
display: block;
color: #333;
margin-bottom: 6px;
font-size: 17px;
font-weight: 600;
font-family: "Xingkai SC", "STKaiti", serif;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #9370db;
text-decoration: none;
border-bottom: 1px dashed rgba(147, 112, 219, 0.5);
transition: all 0.3s ease;

styles.ol:
list-style: none;
padding: 0.5em 3.5em;
counter-reset: decorated-counter;
margin-bottom: 1.5em;

styles.li:
color: #444;
font-size: 16px;
line-height: 1.8;
margin: 16px 0;
font-family: "STKaiti", "PingFang SC", sans-serif;

styles.blockquote:
background-color: rgba(248, 248, 255, 0.7);
border-left: 4px solid rgba(221, 160, 221, 0.6);
color: #666;
padding: 15px 20px;
margin: 20px 0;
border-radius: 0 8px 8px 0;
font-style: italic;

styles.pre:
border: 1px solid rgba(173, 216, 230, 0.4);
box-shadow: 0 4px 15px rgba(173, 216, 230, 0.1);
background-color: rgba(248, 248, 255, 0.7);
border-radius: 8px;
padding: 15px;
overflow-x: auto;

styles.hr:
height: 2px;
border: none;
background: linear-gradient(
  to right,
  transparent,
  rgba(173, 216, 230, 0.5),
  rgba(221, 160, 221, 0.5),
  rgba(255, 182, 193, 0.5),
  transparent
);
margin: 25px 0;

styles.img:
border: 3px solid rgba(255, 255, 255, 0.8);
box-shadow: 0 5px 15px rgba(173, 216, 230, 0.3);
border-radius: 8px;
max-width: 100%;
height: auto;
margin: 15px 0;
transition: transform 0.3s ease;

styles.table:
box-shadow: 0 4px 15px rgba(173, 216, 230, 0.2);
border-radius: 8px;
overflow: hidden;
border-collapse: collapse;
margin: 20px 0;

styles.th:
background-color: rgba(173, 216, 230, 0.2);
color: #333;
border-bottom: 2px solid rgba(173, 216, 230, 0.4);
padding: 10px 15px;
text-align: left;
